package com.soumyajit.gradlemc.foundation;
import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;

/** Small lifecycle-owned executor. Only immutable snapshots/evidence may cross to WORKER_SAFE tasks. */
public final class FoundationEngine implements AutoCloseable {
 private final TaskRegistry registry;private final TaskHistory history;private final ThreadPoolExecutor workers;private final Map<TaskId,TaskCore.TaskResult> latest=new HashMap<>();private TaskCore.CancellationToken active;
 public FoundationEngine(TaskRegistry registry){this.registry=Objects.requireNonNull(registry);history=new TaskHistory(64);workers=GradleMcRuntimeExecutor.lane(GradleMcRuntimeExecutor.Lane.SHORT_ANALYSIS);}
 public synchronized TaskCore.Plan dryRun(TaskId id,TaskCore.Context context,boolean force){return registry.plan(List.of(id),context,force);}
 public synchronized TaskCore.Plan plan(List<TaskId> ids,TaskCore.Context context,boolean force){return registry.plan(ids,context,force);}
 public synchronized Optional<TaskCore.CancellationToken> activeExecution(){return Optional.ofNullable(active);}
 public synchronized boolean cancelActive(){return active!=null&&active.cancel();}
 public synchronized List<TaskCore.TaskResult> history(){return history.recent();}
 public List<TaskCore.TaskResult> execute(TaskId id,TaskCore.Context input,boolean force){return execute(List.of(id),input,force);}
 /** Executes one Foundation-planned multi-root graph exactly once, in its dependency-first order. */
 public List<TaskCore.TaskResult> execute(List<TaskId> ids,TaskCore.Context input,boolean force){
  Objects.requireNonNull(ids,"ids");Objects.requireNonNull(input,"input");
  // The request owns its cancellation token.  In particular, cancelling one Investigation must
  // never signal a separately owned Foundation execution.
  TaskCore.CancellationToken token=input.cancellation();
  synchronized(this){if(active!=null)throw new IllegalStateException("A diagnostic execution is already active");active=token;}
  try{
   TaskCore.Context context=new TaskCore.Context(input.clock(),token,input.staticFingerprint(),input.runtimeFingerprint(),Map.of(),input.capabilities());
   TaskCore.Plan plan=registry.plan(ids,context,force);Map<TaskId,TaskCore.TaskResult> run=new HashMap<>();List<TaskCore.TaskResult> results=new ArrayList<>();
   for(TaskCore.PlanNode node:plan.nodes()){TaskCore.TaskResult result=executeNode(node,context,run,force);run.put(node.id(),result);results.add(result);synchronized(this){latest.put(node.id(),result);history.add(result);}}
   return List.copyOf(results);
  }finally{synchronized(this){active=null;}}
 }
 private TaskCore.TaskResult executeNode(TaskCore.PlanNode node,TaskCore.Context base,Map<TaskId,TaskCore.TaskResult> run,boolean force){TaskCore.Definition task=registry.get(node.id()).orElseThrow();Instant queued=base.clock().instant();if(base.cancellation().cancelled())return result(task,TaskCore.State.CANCELLED,queued,null,base.clock().instant(),"Cancelled before execution",base,null);if(task.affinity()==TaskCore.Affinity.UNAVAILABLE_ON_THIS_SIDE||!node.availability().available())return result(task,TaskCore.State.UNAVAILABLE,queued,null,base.clock().instant(),node.availability().reason(),base,null);for(TaskId dependency:task.dependencies()){TaskCore.TaskResult previous=run.get(dependency);if(previous==null||previous.state()!=TaskCore.State.SUCCEEDED)return result(task,TaskCore.State.SKIPPED,queued,null,base.clock().instant(),"Skipped because dependency "+dependency+" did not succeed",base,null);}TaskCore.TaskResult cached; synchronized(this){cached=latest.get(task.id());}if(!force&&reusable(task,cached,base))return result(task,TaskCore.State.SUCCEEDED,queued,base.clock().instant(),base.clock().instant(),"Reused current process result",base,cached.output().orElse(null));Instant started=base.clock().instant();TaskCore.Context context=new TaskCore.Context(base.clock(),base.cancellation(),base.staticFingerprint(),base.runtimeFingerprint(),run,base.capabilities());try{TaskCore.Output out;if(task.affinity()==TaskCore.Affinity.WORKER_SAFE){Future<TaskCore.Output> f=workers.submit(()->task.body().run(context));try{out=f.get(task.timeout().toMillis(),TimeUnit.MILLISECONDS);}catch(TimeoutException e){base.cancellation().cancel();f.cancel(true);return result(task,TaskCore.State.TIMED_OUT,queued,started,base.clock().instant(),"Timed out after "+task.timeout().toMillis()+" ms",base,null);}}else if(task.affinity()==TaskCore.Affinity.SERVER_MAIN_THREAD_CAPTURE){GameThreadRequest<TaskCore.Output> request=new GameThreadRequest<>("foundation-"+task.id().value().replace(':','-'),task.displayName(),GameThreadTarget.SERVER_MAIN_THREAD_CAPTURE,task.timeout(),base.cancellation(),()->task.body().run(context));GameThreadResult<TaskCore.Output> dispatched=ForgeGameThreadBridgeService.bridge().dispatch(request).get(task.timeout().toMillis(),TimeUnit.MILLISECONDS);if(dispatched.status()!=GameThreadBridgeStatus.COMPLETED)return result(task,dispatched.status()==GameThreadBridgeStatus.CANCELLED?TaskCore.State.CANCELLED:dispatched.status()==GameThreadBridgeStatus.TIMED_OUT?TaskCore.State.TIMED_OUT:TaskCore.State.UNAVAILABLE,queued,started,base.clock().instant(),dispatched.detail()+" queueDelayMs="+dispatched.queueDelay().toMillis(),base,null);out=dispatched.value().orElseThrow();}else if(task.affinity()==TaskCore.Affinity.CLIENT_MAIN_THREAD_CAPTURE){return result(task,TaskCore.State.UNAVAILABLE,queued,started,base.clock().instant(),"Client capture is unavailable in the server Foundation engine",base,null);}else{out=task.body().run(context);if(Duration.between(started,base.clock().instant()).compareTo(task.timeout())>0){base.cancellation().cancel();return result(task,TaskCore.State.TIMED_OUT,queued,started,base.clock().instant(),"Timeout requested; caller-safe work was not forcibly stopped",base,null);}}if(base.cancellation().cancelled())return result(task,TaskCore.State.CANCELLED,queued,started,base.clock().instant(),"Cancelled cooperatively",base,null);return result(task,TaskCore.State.SUCCEEDED,queued,started,base.clock().instant(),"Completed",base,out);}catch(InterruptedException e){Thread.currentThread().interrupt();return result(task,TaskCore.State.CANCELLED,queued,started,base.clock().instant(),"Interrupted while cancellation was requested",base,null);}catch(ExecutionException|RejectedExecutionException e){return result(task,TaskCore.State.FAILED,queued,started,base.clock().instant(),"Execution failed: "+e.getClass().getSimpleName(),base,null);}catch(TimeoutException e){base.cancellation().cancel();return result(task,TaskCore.State.TIMED_OUT,queued,started,base.clock().instant(),"Timed out waiting for game-thread capture",base,null);}catch(Exception e){return result(task,TaskCore.State.FAILED,queued,started,base.clock().instant(),"Execution failed: "+e.getClass().getSimpleName(),base,null);}}
 private static boolean reusable(TaskCore.Definition task,TaskCore.TaskResult old,TaskCore.Context now){if(old==null||old.state()!=TaskCore.State.SUCCEEDED||task.cachePolicy()==TaskCore.CachePolicy.NEVER_CACHE||task.cachePolicy()==TaskCore.CachePolicy.ALWAYS_RUN)return false;if(task.cachePolicy()==TaskCore.CachePolicy.STATIC_FINGERPRINT)return old.staticFingerprint().equals(Optional.of(now.staticFingerprint()));if(task.cachePolicy()==TaskCore.CachePolicy.RUNTIME_CONTEXT)return old.runtimeFingerprint().equals(Optional.of(now.runtimeFingerprint()));return task.cachePolicy()==TaskCore.CachePolicy.PROCESS_LIFETIME;}
 private static TaskCore.TaskResult result(TaskCore.Definition task,TaskCore.State state,Instant queued,Instant started,Instant completed,String reason,TaskCore.Context context,TaskCore.Output output){List<String> ids=output==null?List.of():output.evidence().stream().map(Evidence::id).toList();Freshness f=new Freshness(state==TaskCore.State.SUCCEEDED?Freshness.State.FRESH:Freshness.State.UNAVAILABLE,completed,Optional.empty(),"task-engine",reason,List.of());return new TaskCore.TaskResult(task.id(),state,queued,started,completed,reason,List.of(),state==TaskCore.State.FAILED?List.of(reason):List.of(),ids,f,Optional.of(context.staticFingerprint()),Optional.of(context.runtimeFingerprint()),Optional.ofNullable(output));}
 @Override public void close(){cancelActive();}
}
